const kmBetween = (a, b) => {
  const R = 6371, d = Math.PI / 180;
  const dLat = (b[1] - a[1]) * d, dLon = (b[2] - a[2]) * d;
  const x = Math.sin(dLat / 2) ** 2 + Math.cos(a[1] * d) * Math.cos(b[1] * d) * Math.sin(dLon / 2) ** 2;
  return Math.round(2 * R * Math.asin(Math.sqrt(x)));
};

